{
  "title":"Kế hoạch câu hỏi nâng cao – Nhiệt động lực học",
  "category":"categories.science",
  "plans":[
    {
      "id":"P11",
      "type":"true_false",
      "recordIds":["F11"],
      "intent":"Xác định xem phát biểu \"Nếu Y = 300°, thì giá trị X tương ứng trên cùng đường thẳng là 140° và nằm trong khoảng hợp lệ của đồ thị\" là đúng hay sai.",
      "reasoningSteps":["Tính hệ số dốc của đường thẳng qua (0,32) và (100,212)","Dùng phương trình Y = 32 + 1.8 X để tính X khi Y = 300° và kiểm tra xem X có nằm trong khoảng 0‑100° hay không"]
    },
    {
      "id":"P12",
      "type":"short_answer",
      "recordIds":["F12"],
      "intent":"Cho p₁ = 5 atm, V₁ = 10 L, T₁ = 300 K, V₂ = 2 L. Tìm nhiệt độ tối đa T₂ (K) sao cho áp suất cuối cùng p₂ không vượt quá 12 atm.",
      "reasoningSteps":["Áp dụng định luật khí hỗn hợp (p₁V₁)/T₁ = (p₂V₂)/T₂","Đặt p₂ = 12 atm và giải bất phương trình cho T₂, tính giá trị lớn nhất của T₂"]
    },
    {
      "id":"P13",
      "type":"multiple_choice",
      "recordIds":["F14","F15"],
      "intent":"Khi 1 g băng ở 0 °C được cho vào 1 g nước ở 40 °C (không xét nhiệt dung của bình), xác định khối lượng băng tan và nhiệt độ cuối cùng của hệ.",
      "reasoningSteps":["Tính nhiệt lượng Q_water = m·c·ΔT do nước nguội tới 0 °C","So sánh Q_water với Q_melt = m_ice·L_f để xác định lượng băng tan","Kết luận nhiệt độ cuối cùng là 0 °C và lượng băng tan bằng Q_water/L_f"]
    },
    {
      "id":"P14",
      "type":"selection",
      "recordIds":["F15","F14"],
      "intent":"Chọn các phát biểu đúng về trạng thái cân bằng của hệ gồm 1 g băng 0 °C và 1 g nước 40 °C (không xét nhiệt dung của bình).",
      "reasoningSteps":["Sử dụng cân bằng năng lượng Q_water = Q_melt để tính lượng băng tan","Xác định nhiệt độ cuối cùng (0 °C) vì còn băng tồn tại","Từ kết quả suy ra các khối lượng nước và băng tại cân bằng"]
    },
    {
      "id":"P15",
      "type":"true_false",
      "recordIds":["F16"],
      "intent":"Phát biểu \"Trong chu trình tủ lạnh, nhiệt lượng Q₂ mà môi chất làm lạnh thải ra môi trường bằng 720 kJ\" là đúng.",
      "reasoningSteps":["Tính Q₁ = COP·A = 3 × 180 kJ = 540 kJ","Dùng định luật năng lượng cho tủ lạnh Q₂ = Q₁ + A để tính Q₂ = 540 kJ + 180 kJ = 720 kJ"]
    }
  ]
}
